type Mutable = Record<string, unknown>;
type Path = readonly string[];
const attemptSchema = "review-attempt-result/v1";
const authoritySchema = "review-authority/v1";
const kinds = ["SWEEP_COMPLETE", "BLOCKED", "INCOMPLETE", "FAILED", "MALFORMED"] as const;
const reasons = [
  "RESULT_UNAVAILABLE",
  "RESULT_INVALID",
  "RESULT_NONCOMPLETE",
  "HISTORY_UNPROVEN",
  "INDEPENDENCE_UNPROVEN",
  "TARGET_CHANGED",
  "EVIDENCE_UNPROVEN",
] as const;
const changedDigest = "9876543210abcdef".repeat(4);
const uuid = (suffix: number): string =>
  `01900000-0000-7000-8000-${String(suffix).padStart(12, "0")}`;
const copy = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const fixture = (index = 0): Mutable => JSON.parse(goldens[index]!.text) as Mutable;
const at = (value: unknown, path: Path = []): Mutable =>
  path.reduce((v, key) => (v as Mutable)[key], value) as Mutable;
function replace(input: Mutable, path: Path, value: unknown): Mutable {
  if (!path.length) return value as Mutable;
  at(input, path.slice(0, -1))[path.at(-1)!] = value;
  return input;
}
function recordPaths(value: unknown, path: string[] = []): string[][] {
  if (value === null || typeof value !== "object") return [];
  return [
    ...(Array.isArray(value) ? [] : [path]),
    ...Object.entries(value).flatMap(([key, child]) => recordPaths(child, [...path, key])),
  ];
}
function shuffle(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(shuffle);
  return value && typeof value === "object"
    ? Object.fromEntries(
        Object.entries(value)
          .reverse()
          .map(([key, child]) => [key, shuffle(child)]),
      )
    : value;
}
const encode = (text: string): Uint8Array => new TextEncoder().encode(text);
const sha = (value: string | Uint8Array): string =>
  createHash("sha256").update(value).digest("hex");
const parse = (schema: string, value: unknown): contracts.ParseResult =>
  schema === attemptSchema
    ? contracts.parseReviewAttemptResult(value)
    : contracts.parseReviewAuthority(value);
const digest = (schema: string, value: unknown): string =>
  schema === attemptSchema
    ? contracts.computeReviewAttemptResultDigest(value)
    : contracts.computeReviewAuthorityDigest(value);
function refuse(schema: string, value: unknown): void {
  expect(parse(schema, value).ok).toBe(false);
  expect(contracts.parseContract(schema, value).ok).toBe(false);
  expect(contracts.serializeContract(schema, value).ok).toBe(false);
  expect(() => digest(schema, value)).toThrow(TypeError);
}

// Relation fixtures deliberately use public subject/request identities. They are not byte goldens.
function request(target: "TREE" | "ORDERED" | "CANDIDATE" = "TREE"): Mutable {
  const source = { adapterId: "git", projectId: uuid(3), revision: "commit-1" };
  const subject: Mutable =
    target === "CANDIDATE"
      ? {
          assemblyCycleId: uuid(2),
          candidateDigest: "a".repeat(64),
          certificationDigest: "b".repeat(64),
          landedSource: source,
          landedTreeDigest: "c".repeat(64),
          manifestDigest: "d".repeat(64),
          schemaVersion: "release-candidate-subject/v1",
          testBundleDigest: "e".repeat(64),
        }
      : {
          authorAttemptId: uuid(1),
          authorCycleId: uuid(2),
          baseSource: source,
          result:
            target === "TREE"
              ? { kind: "TREE", treeDigest: "a".repeat(64) }
              : {
                  entries: [
                    { contentDigest: "a".repeat(64), kind: "PATCH" },
                    { contentDigest: "b".repeat(64), kind: "ARTIFACT" },
                  ],
                  kind: "ORDERED_PATCH_ARTIFACTS",
                },
          schemaVersion: "worker-result-subject/v1",
          terminalReceiptDigest: "b".repeat(64),
        };
  const subjectDigest =
    target === "CANDIDATE"
      ? contracts.computeReleaseCandidateSubjectDigest(subject)
      : contracts.computeWorkerResultSubjectDigest(subject);
  const directiveKinds = [
    "ACCEPTANCE_EVIDENCE",
    "CONSTRAINT",
    "DECISION",
    "NON_GOAL",
    "OPERATOR_ACTION",
    "REVIEW_ATTACK",
    "SCOPE_EXCLUDE",
    "SCOPE_INCLUDE",
    "VERIFICATION",
  ];
  return {
    packet: {
      brief: {
        action: {
          actionCoreDigest: "3".repeat(64),
          actionKind: "work.review",
          capabilityName: "work.read",
          immutableSubjectDigest: subjectDigest,
          moduleDescriptorDigest: "4".repeat(64),
          schemaVersion: "dispatch-brief-action/v1",
        },
        directives: directiveKinds.map((directiveKind) => ({
          code: directiveKind === "OPERATOR_ACTION" ? null : "review",
          directiveKind,
          presence: directiveKind === "OPERATOR_ACTION" ? "ABSENT" : "PRESENT",
          schemaVersion: "dispatch-brief-directive/v1",
          subjectDigest,
        })),
        footprint: [
          {
            access: "READ",
            resourceIdentityDigest: "5".repeat(64),
            schemaVersion: "dispatch-brief-resource/v1",
          },
        ],
        role: "review",
        schemaVersion: "dispatch-brief/v1",
      },
      evidence: [],
      subject,
    },
    reviewCycleId: uuid(5),
    schemaVersion: "review-request/v1",
  };
}
function tuple(
  kind = "SWEEP_COMPLETE",
  outcome = "accepted",
  reason = "EVIDENCE_UNPROVEN",
  selected = true,
  target: "TREE" | "ORDERED" | "CANDIDATE" = "TREE",
): [Mutable, Mutable | null, Mutable] {
  const req = request(target);
  const identities = {
    packetDigest: contracts.computeReviewPacketDigest(req.packet),
    requestDigest: contracts.computeReviewRequestDigest(req),
    subjectDigest: at(req, ["packet", "brief", "action"]).immutableSubjectDigest,
  };
  const attempt = selected
    ? { ...fixture(kinds.indexOf(kind as (typeof kinds)[number])), ...identities }
    : null;
  const authority = {
    ...fixture(outcome === "accepted" ? 5 : 6),
    ...identities,
    outcome: {
      attemptResultDigest: attempt ? contracts.computeReviewAttemptResultDigest(attempt) : null,
      kind: outcome,
      ...(outcome === "unknown"
        ? { evidence: copy(at(fixture(), ["result"]).evidence), reason }
        : {}),
    },
  };
  return [req, attempt, authority];
}
const bind = (input: readonly [unknown, unknown, unknown]): contracts.ParseResult =>
  contracts.validateReviewResultBinding(...input);
function rehashAttempt(input: [Mutable, Mutable | null, Mutable]): void {
  at(input[2], ["outcome"]).attemptResultDigest = contracts.computeReviewAttemptResultDigest(
    input[1],
  );
}

describe("review result evidence and claimed authority structural contracts", () => {
  test("pins every result/outcome/reason cell's canonical bytes, full frames and identities", () => {
    for (const [index, golden] of goldens.entries()) {
      const value = fixture(index),
        expected = { ok: true, value };
      expect(parse(golden.schema, value)).toEqual(expected);
      expect(contracts.parseReviewResultContract(golden.schema, value)).toEqual(expected);
      expect(contracts.parseContract(golden.schema, value)).toEqual(expected);
      expect(contracts.parseCanonicalContractBytes(golden.schema, encode(golden.text))).toEqual(
        expected,
      );
      expect(contracts.canonicalJson(value)).toBe(golden.text);
      expect(digest(golden.schema, value)).toBe(golden.digest);
      expect(
        Buffer.from(
          contracts.framedBytes(golden.schema, [
            contracts.frame.canonical(value as contracts.ContractRecord),
          ]),
        ).toString("hex"),
      ).toBe(golden.frameHex);
      expect(sha(Buffer.from(golden.frameHex, "hex"))).toBe(golden.digest);
      for (const reordered of [value, shuffle(value)])
        expect(contracts.serializeContract(golden.schema, reordered)).toEqual({
          ok: true,
          bytes: encode(golden.text),
          digest: golden.digest,
        });
      expect(sha(golden.text)).not.toBe(golden.digest);
      const frame = Buffer.from(golden.frameHex, "hex"),
        prefix = Buffer.byteLength(`orchestration-platform\0${golden.schema}\0`);
      for (const offset of [prefix - 2, prefix + 3, prefix + 4, prefix + 12, frame.length - 1]) {
        const changed = Buffer.from(frame);
        changed[offset] = changed[offset]! ^ 1;
        expect(sha(changed)).not.toBe(golden.digest);
      }
    }
  });

  test("closes every arm and nested field against omissions, renaming, extra fields and wrong types", () => {
    for (const [index, golden] of goldens.entries())
      for (const path of recordPaths(fixture(index))) {
        const value = at(fixture(index), path);
        for (const [key, original] of Object.entries(value)) {
          const removed = { ...value };
          delete removed[key];
          const allowsNull =
            key === "attemptResultDigest" &&
            value.kind === "unknown" &&
            ["INDEPENDENCE_UNPROVEN", "TARGET_CHANGED", "EVIDENCE_UNPROVEN"].includes(
              String(value.reason),
            );
          for (const changed of [
            removed,
            { ...removed, [key.toUpperCase()]: original },
            ...[null, undefined, false, 1, "", [], {}, 1n, Symbol("invalid")]
              .filter((wrong) => wrong !== original && !(wrong === null && allowsNull))
              .map((wrong) => ({ ...value, [key]: wrong })),
          ])
            refuse(golden.schema, replace(fixture(index), path, changed));
        }
        for (const extra of [
          "extra",
          "authority",
          "findings",
          "reason",
          "severity",
          "issuer",
          "signature",
          "complete",
          "schemaVersion",
          "__proto__",
        ])
          if (!(extra in value))
            refuse(golden.schema, replace(fixture(index), path, { ...value, [extra]: true }));
      }
    for (const index of [0, 5])
      for (const version of ["v0", "v2", "v1\n"])
        refuse(goldens[index]!.schema, {
          ...fixture(index),
          schemaVersion: goldens[index]!.schema.replace("v1", version),
        });
    for (const kind of ["ACCEPTED", "accepted", "PARTIAL", "SWEEP_COMPLETE\n"])
      refuse(attemptSchema, replace(fixture(), ["result", "kind"], kind));
    for (const kind of ["ACCEPTED", "SWEEP_COMPLETE", "pending", "accepted\n"])
      refuse(authoritySchema, replace(fixture(5), ["outcome", "kind"], kind));
    for (const reason of ["ABSENT", "result_invalid", "RESULT_INVALID\n"])
      refuse(authoritySchema, replace(fixture(7), ["outcome", "reason"], reason));
  });

  test("rejects hostile records and arrays at every nested boundary without evaluating caller code", () => {
    let calls = 0;
    const invoked = (): never => {
      calls++;
      throw new Error("caller code invoked");
    };
    for (const index of [1, 7])
      for (const path of recordPaths(fixture(index))) {
        const value = at(fixture(index), path),
          key = Object.keys(value)[0]!;
        const getter = { ...value };
        Object.defineProperty(getter, key, { enumerable: true, get: invoked });
        const hidden = { ...value };
        Object.defineProperty(hidden, "hidden", { value: 1 });
        const revoked = Proxy.revocable(value, {});
        revoked.revoke();
        const cyclic = { ...value };
        cyclic[key] = cyclic;
        for (const hostile of [
          getter,
          hidden,
          cyclic,
          { ...value, [Symbol("extra")]: true },
          Object.assign(Object.create({ inherited: true }), value),
          new Proxy(value, {}),
          new Proxy(value, { get: invoked, ownKeys: invoked, getPrototypeOf: invoked }),
          revoked.proxy,
          new Date(),
          runInNewContext("({})"),
        ])
          refuse(goldens[index]!.schema, replace(fixture(index), path, hostile));
        for (const benign of [
          Object.freeze(value),
          Object.seal({ ...value }),
          Object.assign(Object.create(null), value),
        ])
          expect(parse(goldens[index]!.schema, replace(fixture(index), path, benign)).ok).toBe(
            true,
          );
      }
    for (const [index, path] of [
      [1, ["result", "evidence"]],
      [1, ["result", "findings"]],
      [7, ["outcome", "evidence"]],
    ] as const) {
      const values = at(fixture(index), path) as unknown as unknown[];
      const getter = [...values];
      Object.defineProperty(getter, "0", { enumerable: true, get: invoked });
      const revoked = Proxy.revocable(values, {});
      revoked.revoke();
      class SubArray extends Array<unknown> {}
      for (const hostile of [
        new Array(1),
        getter,
        new Proxy(values, {}),
        revoked.proxy,
        Object.assign([...values], { extra: true }),
        Object.assign([...values], { [Symbol.iterator]: invoked }),
        new SubArray(...values),
        runInNewContext("[]"),
      ])
        refuse(goldens[index]!.schema, replace(fixture(index), path, hostile));
      for (const benign of [Object.freeze([...values]), Object.seal([...values])])
        expect(parse(goldens[index]!.schema, replace(fixture(index), path, benign)).ok).toBe(true);
      const input = fixture(index),
        parsed = parse(goldens[index]!.schema, input);
      (at(input, path) as unknown as unknown[]).length = 0;
      expect(parsed.ok).toBe(true);
      if (parsed.ok) {
        expect(at(parsed.value, path)).toHaveLength(values.length);
        expect(Object.isFrozen(at(parsed.value, path))).toBe(true);
      }
    }
    expect(calls).toBe(0);
  });

  test("enforces list bounds, retained decimal/digest scalars, finding order and opaque code/ID grammar", () => {
    for (const [index, path] of [
      [0, ["result", "evidence"]],
      [1, ["result", "findings"]],
      [7, ["outcome", "evidence"]],
    ] as const) {
      const entry = at(fixture(index), [...path, "0"]);
      for (const length of [0, 1, 256, 257]) {
        const entries = Array.from({ length }, (_, i) =>
          path[1] === "findings"
            ? { ...copy(entry), findingId: `block-${String(i).padStart(3, "0")}` }
            : copy(entry),
        );
        const input = replace(fixture(index), path, entries);
        if (length === 1 || length === 256)
          expect(parse(goldens[index]!.schema, input).ok).toBe(true);
        else refuse(goldens[index]!.schema, input);
      }
    }
    for (const [index, golden] of goldens.entries())
      for (const path of recordPaths(fixture(index))) {
        for (const [key, value] of Object.entries(at(fixture(index), path))) {
          const bad =
            key.endsWith("Digest") && value !== null
              ? [
                  "A".repeat(64),
                  "g".repeat(64),
                  "a".repeat(63),
                  "a".repeat(65),
                  "a".repeat(64) + "\n",
                ]
              : key === "byteLength"
                ? [
                    "-0",
                    "-1",
                    "00",
                    "01",
                    "+1",
                    "1.0",
                    "1e2",
                    "9007199254740992",
                    "999999999999999999",
                    "0\n",
                    " 1",
                    "1\r\n",
                  ]
                : key === "attemptId" || key === "cycleId"
                  ? [
                      uuid(8).replace("7000", "4000"),
                      uuid(8).replace("8000", "0000"),
                      uuid(8) + "\n",
                    ]
                  : [];
          for (const wrong of bad)
            refuse(golden.schema, replace(fixture(index), [...path, key], wrong));
        }
      }
    for (const [key, valid, invalid] of [
      [
        "code",
        ["a", "a".repeat(64), "a0._:-"],
        ["A", "0fix", "a".repeat(65), "a@b", "a+b", "a b", "a\n"],
      ],
      ["findingId", ["0", "a".repeat(128), "a0._:@+-"], ["A", "a".repeat(129), "_a", "a b", "a\n"]],
    ] as const) {
      const path = ["result", "findings", "0", ...(key === "code" ? ["disposition"] : []), key];
      for (const value of valid)
        expect(contracts.parseReviewAttemptResult(replace(fixture(1), path, value)).ok).toBe(true);
      for (const value of invalid) refuse(attemptSchema, replace(fixture(1), path, value));
    }
    const finding = at(fixture(1), ["result", "findings", "0"]);
    for (const entries of [
      [finding, finding],
      [
        { ...finding, findingId: "b" },
        { ...finding, findingId: "a" },
      ],
      [
        finding,
        { ...finding, disposition: { code: "different", moduleDescriptorDigest: "4".repeat(64) } },
      ],
    ])
      refuse(attemptSchema, replace(fixture(1), ["result", "findings"], entries));
    for (const index of [0, 7]) {
      const path = [index === 0 ? "result" : "outcome", "evidence"],
        entry = at(fixture(index), [...path, "0"]);
      const repeated = replace(fixture(index), path, [entry, entry]);
      expect(parse(goldens[index]!.schema, repeated).ok).toBe(true);
      expect(digest(goldens[index]!.schema, repeated)).not.toBe(
        digest(goldens[index]!.schema, replace(fixture(index), path, [entry])),
      );
      const reordered = fixture(index);
      (at(reordered, path) as unknown as unknown[]).reverse();
      expect(digest(goldens[index]!.schema, reordered)).not.toBe(goldens[index]!.digest);
    }
  });

  test("refuses noncanonical persisted bytes and registers only the two closed families", () => {
    for (const [index, golden] of goldens.entries()) {
      const text = golden.text;
      for (const changed of [
        text.slice(0, -1),
        text + "\n",
        text.replace(/\n$/, "\r\n"),
        " " + text,
        "\ufeff" + text,
        JSON.stringify(shuffle(fixture(index))) + "\n",
        text.replace("{", '{"schemaVersion":"' + golden.schema + '",'),
        text.replace(golden.schema, golden.schema.replace("v1", "v2")),
      ])
        expect(contracts.parseCanonicalContractBytes(golden.schema, encode(changed)).ok).toBe(
          false,
        );
      for (const bytes of [
        Uint8Array.of(0xff),
        new Proxy(encode(text), {}),
        runInNewContext("new Uint8Array()") as Uint8Array,
      ])
        expect(contracts.parseCanonicalContractBytes(golden.schema, bytes).ok).toBe(false);
    }
    expect(contracts.reviewResultSchemaVersions).toEqual([attemptSchema, authoritySchema]);
    expect(contracts.reviewResultKinds).toEqual(kinds);
    expect(contracts.reviewAuthorityUnknownReasons).toEqual(reasons);
    for (const schema of [attemptSchema, authoritySchema]) {
      expect(contracts.schemaVersions.filter((value) => value === schema)).toHaveLength(1);
      expect(contracts.compatibilityDisposition(schema, schema)).toBe("readable");
    }
    for (const schema of [
      "review-attempt-result/v2",
      "review-authority/v2",
      "review-finding/v1",
      "review-outcome/v1",
      "review-packet/v1",
    ]) {
      expect(contracts.parseReviewResultContract(schema, fixture())).toBeNull();
      expect(contracts.parseContract(schema, fixture()).ok).toBe(false);
      expect(contracts.serializeContract(schema, fixture()).ok).toBe(false);
      expect(contracts.compatibilityDisposition(schema, schema)).toBe("refused");
    }
    for (const journalSchema of [
      "orchestration-event/v1",
      "event-journal/v1",
      "reduced-state/v1",
      "cycle-receipt/v1",
    ]) {
      expect(contracts.parseReviewResultContract(journalSchema, fixture())).toBeNull();
      expect(contracts.parseContract(journalSchema, fixture()).ok).toBe(false);
      expect(contracts.serializeContract(journalSchema, fixture()).ok).toBe(false);
      expect(contracts.compatibilityDisposition(journalSchema, journalSchema)).toBe("readable");
    }
    // The supported terminal family still refuses a review result as its body.
    expect(contracts.parseContract("worker-terminal-receipt/v1", fixture()).ok).toBe(false);
    expect(contracts.serializeContract("worker-terminal-receipt/v1", fixture()).ok).toBe(false);
  });

  test("binds the full decided/unknown result-kind and nullability matrix for all concrete targets", () => {
    for (const target of ["TREE", "ORDERED", "CANDIDATE"] as const) {
      for (const outcome of ["accepted", "rejected"])
        for (const kind of kinds) {
          const input = tuple(kind, outcome, "", true, target);
          expect(bind(input).ok).toBe(
            kind === (outcome === "accepted" ? "SWEEP_COMPLETE" : "BLOCKED"),
          );
        }
      for (const reason of reasons)
        for (const selected of [false, true]) {
          const nullOnly = ["RESULT_UNAVAILABLE", "RESULT_INVALID", "HISTORY_UNPROVEN"].includes(
            reason,
          );
          const admissible = selected ? !nullOnly : reason !== "RESULT_NONCOMPLETE";
          for (const kind of kinds) {
            const input = tuple(kind, "unknown", reason, selected, target);
            expect(contracts.parseReviewAuthority(input[2]).ok).toBe(admissible);
            expect(bind(input).ok).toBe(
              admissible &&
                !(
                  selected &&
                  reason === "RESULT_NONCOMPLETE" &&
                  ["SWEEP_COMPLETE", "BLOCKED"].includes(kind)
                ),
            );
          }
        }
    }
    // Valid capture of malformed worker bytes is evidence; malformed enclosing records refuse.
    const malformed = tuple("MALFORMED", "unknown", "RESULT_NONCOMPLETE");
    expect(bind(malformed).ok).toBe(true);
    delete malformed[1]!.terminalReceiptDigest;
    expect(bind(malformed).ok).toBe(false);
  });

  test("independently discriminates every supplied identity, cycle, attempt and finding-module equality", () => {
    for (const field of ["packetDigest", "requestDigest", "subjectDigest"]) {
      const authorityMismatch = tuple();
      authorityMismatch[2][field] = changedDigest;
      expect(bind(authorityMismatch).ok).toBe(false);
      const attemptMismatch = tuple();
      attemptMismatch[1]![field] = changedDigest;
      rehashAttempt(attemptMismatch);
      expect(bind(attemptMismatch).ok).toBe(false);
    }
    const wrongReference = tuple();
    at(wrongReference[2], ["outcome"]).attemptResultDigest = changedDigest;
    expect(bind(wrongReference).ok).toBe(false);
    for (const [field, value] of [
      ["cycleId", uuid(8)],
      ["attemptId", uuid(1)],
    ] as const) {
      const input = tuple();
      input[1]![field] = value;
      rehashAttempt(input);
      expect(contracts.parseReviewAttemptResult(input[1]).ok).toBe(true);
      expect(bind(input).ok).toBe(false);
    }
    const moduleMismatch = tuple("BLOCKED", "rejected");
    const original = at(moduleMismatch[1], ["result", "findings", "0"]);
    at(moduleMismatch[1], ["result"]).findings = [
      original,
      { ...copy(original), findingId: "block-002" },
    ];
    rehashAttempt(moduleMismatch);
    expect(bind(moduleMismatch).ok).toBe(true);
    for (const index of ["0", "1"]) {
      const input = copy(moduleMismatch);
      at(input[1], ["result", "findings", index, "disposition"]).moduleDescriptorDigest =
        changedDigest;
      rehashAttempt(input);
      expect(bind(input).ok).toBe(false);
    }
    for (const field of ["dispatchPlanDigest", "launchReceiptDigest", "terminalReceiptDigest"]) {
      const input = tuple();
      input[1]![field] = changedDigest;
      expect(bind(input).ok).toBe(false); // Stale authority must not bind altered evidence references.
      rehashAttempt(input);
      expect(bind(input).ok).toBe(true); // Their actual preimage joins are deferred.
    }
  });

  test("rejects substituted requests, malformed tuple members and both directions of null binding", () => {
    for (const [path, value] of [
      [["reviewCycleId"], uuid(8)],
      [["packet", "evidence"], [at(fixture(), ["result", "evidence", "0"])]],
      [["packet", "brief", "action", "moduleDescriptorDigest"], changedDigest],
      [["packet", "brief", "directives", "0", "code"], "changed"],
    ] as const) {
      const input = tuple();
      replace(input[0], path, value);
      expect(contracts.parseReviewRequest(input[0]).ok).toBe(true);
      expect(bind(input).ok).toBe(false);
    }
    for (const target of ["TREE", "ORDERED", "CANDIDATE"] as const) {
      const input = tuple("SWEEP_COMPLETE", "accepted", "", true, target);
      const subject = at(input[0], ["packet", "subject"]);
      subject[target === "CANDIDATE" ? "candidateDigest" : "terminalReceiptDigest"] = changedDigest;
      const subjectDigest =
        target === "CANDIDATE"
          ? contracts.computeReleaseCandidateSubjectDigest(subject)
          : contracts.computeWorkerResultSubjectDigest(subject);
      at(input[0], ["packet", "brief", "action"]).immutableSubjectDigest = subjectDigest;
      for (const directive of at(input[0], ["packet", "brief"]).directives as Mutable[])
        directive.subjectDigest = subjectDigest;
      expect(contracts.parseReviewRequest(input[0]).ok).toBe(true);
      expect(bind(input).ok).toBe(false);
      const sameCycle = tuple("SWEEP_COMPLETE", "accepted", "", true, target);
      sameCycle[0].reviewCycleId = uuid(2);
      expect(bind(sameCycle).ok).toBe(false);
    }
    for (const index of [0, 1, 2])
      for (const wrong of [undefined, null, {}, "unavailable", new Proxy({}, {})]) {
        const input: [unknown, unknown, unknown] = tuple();
        input[index] = wrong;
        expect(bind(input).ok).toBe(false);
      }
    const noSelected = tuple("SWEEP_COMPLETE", "unknown", "EVIDENCE_UNPROVEN", false);
    expect(bind(noSelected).ok).toBe(true);
    noSelected[1] = tuple()[1];
    expect(bind(noSelected).ok).toBe(false);
    for (const outcome of ["accepted", "rejected", "unknown"]) {
      const input = tuple(outcome === "rejected" ? "BLOCKED" : "SWEEP_COMPLETE", outcome);
      input[1] = null;
      expect(bind(input).ok).toBe(false);
    }
    // Candidate uses real assembly identity and no fabricated author attempt. Earlier UUID order proves nothing.
    const candidate = tuple("SWEEP_COMPLETE", "accepted", "", true, "CANDIDATE");
    candidate[1]!.attemptId = uuid(1);
    rehashAttempt(candidate);
    expect(bind(candidate).ok).toBe(true);
    const earlier = tuple();
    earlier[0].reviewCycleId = "01800000-0000-7000-8000-000000000005";
    earlier[1]!.cycleId = earlier[0].reviewCycleId;
    earlier[1]!.requestDigest = earlier[2].requestDigest = contracts.computeReviewRequestDigest(
      earlier[0],
    );
    rehashAttempt(earlier);
    expect(bind(earlier).ok).toBe(true);
  });
});
